import{_ as n,C as o,o as d,c as e,j as t,E as r,a as s,a3 as l}from"./chunks/framework.C6R8kWFE.js";const x=JSON.parse('{"title":"2-hafta (Mentor)","description":"","frontmatter":{"title":"2-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"10-sinf (UX/UI)","link":"/mentor/10-sinf-uxui/"},"n":2,"bob":"II-bob · UX tadqiqotlari va foydalanuvchi ehtiyojlarini aniqlash","lessons":[{"g":4,"title":"4-dars: Foydalanuvchi tadqiqot usullari: intervyu, so‘rovnoma, kuzatish","lead":"Foydalanuvchi tadqiqot usullari: intervyu, so‘rovnoma, kuzatish","link":"/mentor/10-sinf-uxui/hafta-02/dars-1","slide":"/slaydlar/10-sinf-uxui/hafta-02/dars-1.html","test":"/slaydlar/10-sinf-uxui/hafta-02/dars-1-test.html"},{"g":5,"title":"5-dars: Persona va empatiya xaritasini yaratish","lead":"Persona va empatiya xaritasini yaratish","link":"/mentor/10-sinf-uxui/hafta-02/dars-2","slide":"/slaydlar/10-sinf-uxui/hafta-02/dars-2.html","test":"/slaydlar/10-sinf-uxui/hafta-02/dars-2-test.html"},{"g":6,"title":"6-dars: Foydalanuvchi tarixi va senariysini yozish (User Story & User Journey Map)","lead":"Foydalanuvchi tarixi va senariysini yozish (User Story & User Journey Map)","link":"/mentor/10-sinf-uxui/hafta-02/dars-3","slide":"/slaydlar/10-sinf-uxui/hafta-02/dars-3.html","test":"/slaydlar/10-sinf-uxui/hafta-02/dars-3-test.html"}],"test":"/slaydlar/10-sinf-uxui/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"mentor/10-sinf-uxui/hafta-02/index.md","filePath":"mentor/10-sinf-uxui/hafta-02/index.md"}'),h={name:"mentor/10-sinf-uxui/hafta-02/index.md"},u={class:"blk"},y={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},m={class:"blk"},v={id:"baholash-mezoni",tabindex:"-1"};function q(c,a,g,b,f,k){const i=o("Icon");return d(),e("div",null,[t("div",u,[t("h2",y,[r(i,{name:"house"}),a[0]||(a[0]=s(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=l('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h2 id="_4-dars-foydalanuvchi-tadqiqot-usullari-intervyu-so-rovnoma-kuzatish" tabindex="-1">4-dars: Foydalanuvchi tadqiqot usullari: intervyu, so‘rovnoma, kuzatish <a class="header-anchor" href="#_4-dars-foydalanuvchi-tadqiqot-usullari-intervyu-so-rovnoma-kuzatish" aria-label="Permalink to &quot;4-dars: Foydalanuvchi tadqiqot usullari: intervyu, so‘rovnoma, kuzatish&quot;">​</a></h2><ol><li>O&#39;zingiz qiziqqan biror startap loyihasi (masalan, kitobxonlar uchun ijtimoiy tarmoq yoki fitnes mobil ilovasi) mavzusini tanlang.</li><li>Ushbu loyiha uchun maqsadli foydalanuvchilar bilan o&#39;tkazishga mo&#39;ljallangan 4 ta ochiq, yo&#39;naltirilmagan (xolis) sifatli intervyu savolini tuzing.</li><li>Keng auditoriya fikrini o&#39;rganish uchun 3 ta yopiq (shkala yoki variantli tanlov) so&#39;rovnoma savolini shakllantiring.</li><li>Nima uchun faqat do&#39;stlaringiz va sinfdoshlaringizdan intervyu olish yetarli emasligini 2 jumlada asoslang.</li></ol><hr><h2 id="_5-dars-persona-va-empatiya-xaritasini-yaratish" tabindex="-1">5-dars: Persona va empatiya xaritasini yaratish <a class="header-anchor" href="#_5-dars-persona-va-empatiya-xaritasini-yaratish" aria-label="Permalink to &quot;5-dars: Persona va empatiya xaritasini yaratish&quot;">​</a></h2><ol><li>Tanlagan loyihangiz bo&#39;yicha bitta asosiy maqsadli foydalanuvchi uchun to&#39;liq <strong>User Persona</strong> profilini tuzing (Ismi, yoshi, kasbi, shiori, 2 ta asosiy maqsadi, 2 ta og&#39;riqli nuqtasi).</li><li>Ushbu personaj uchun Devid Grey modeli bo&#39;yicha 4 ta asosiy kvadrantli <strong>Empatiya xaritasi</strong>ni (Says, Does, Thinks, Feels) to&#39;ldiring.</li><li>Persona va Empatiya xaritasi sizga qanday yangi g&#39;oyalar berganini 2-3 jumla bilan qayd eting.</li></ol><hr><h2 id="_6-dars-foydalanuvchi-tarixi-va-senariysini-yozish-user-story-user-journey-map" tabindex="-1">6-dars: Foydalanuvchi tarixi va senariysini yozish (User Story &amp; User Journey Map) <a class="header-anchor" href="#_6-dars-foydalanuvchi-tarixi-va-senariysini-yozish-user-story-user-journey-map" aria-label="Permalink to &quot;6-dars: Foydalanuvchi tarixi va senariysini yozish (User Story &amp; User Journey Map)&quot;">​</a></h2><ol><li>Tanlagan loyihangiz uchun Agile standarti (<code>&quot;As a..., I want..., so that...&quot;</code>) bo&#39;yicha 3 ta User Story yozing.</li><li>Ushbu 3 ta User Storydan birini tanlab, unga kamida 3 ta aniq Qabul qilish mezonini (Acceptance Criteria) ishlab chiqing.</li><li>Foydalanuvchining mahsulot bilan ilk tanishuvidan to maqsadiga erishishigacha bo&#39;lgan 4 bosqichli soddalashtirilgan User Journey Map (bosqichlar, foydalanuvchi harakatlari va his-tuyg&#39;ulari) jadvalini tuzing.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>4-dars vazifasi (30 ball):</strong> Ochiq va yo&#39;naltirilmagan intervyu savollari to&#39;g&#39;ri tuzilgani, sifatli va miqdoriy tadqiqot farqi to&#39;g&#39;ri tushunilgani.</li><li><strong>5-dars vazifasi (35 ball):</strong> User Persona realistik va to&#39;liq shakllantirilgani, Empatiya xaritasi kvadrantlari (ayniqsa Thinks va Feels) chuqur tahlil qilingani.</li><li><strong>6-dars vazifasi (35 ball):</strong> User Story formulasi xatosiz qo&#39;llangani, Acceptance Criteria mezonlari aniqligi va User Journey Map bosqichlarining mantiqiyligi.</li></ul><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>O&#39;quvchilar User Story yozishda &quot;so that...&quot; (shunda ... olaman) qismini unutmasligini va UJM da salbiy og&#39;riqli nuqtalarni ko&#39;rsata olganini alohida tekshiring.</li></ul>',16))]),t("div",m,[t("h2",v,[r(i,{name:"list-checks"}),a[3]||(a[3]=s(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=l('<p><strong>Mavzular:</strong></p><ol><li>Foydalanuvchi tadqiqot usullari: sifatli vs miqdoriy, munosabat vs xulq-atvor, intervyu, field study, survey, card sorting</li><li>Persona va empatiya xaritasini yaratish: User Persona komponentlari, Devid Grey Empatiya xaritasi (Says, Does, Thinks, Feels, Pains, Gains)</li><li>Foydalanuvchi tarixi va senariysini yozish: User Story formulasi, Epiklar, Acceptance Criteria, User Journey Map (UJM)</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>UX Tadqiqot Metodlari</strong></td><td>Sifatli va miqdoriy tadqiqotlar farqi, yo&#39;naltirilmagan ochiq intervyu savollari tuzish, card sorting va axborot arxitekturasi</td><td>30 ball</td></tr><tr><td><strong>Persona &amp; Empatiya Xaritasi</strong></td><td>Tadqiqotga asoslangan haqiqiy Persona profili, Empatiya xaritasi 4 kvadranti (ichki va tashqi olam ziddiyatlari), Pains va Gains</td><td>35 ball</td></tr><tr><td><strong>User Story &amp; Journey Map</strong></td><td>Standart User Story formulasi (&quot;As a..., I want..., so that...&quot;), Acceptance Criteria va 4 bosqichli User Journey Map</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>UX Tadqiqot (30)</th><th>Persona &amp; Empathy (35)</th><th>Story &amp; Journey (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar intervyu savollarini tuzishda ko&#39;pincha yo&#39;naltiruvchi (&quot;Bizning sayt sizga yoqdimi?&quot;) savollar berishga moyil bo&#39;lishadi. Ularga xolis, neytral va foydalanuvchining o&#39;tgan real tajribasini so&#39;rovchi savollar berish qoidasini amaliy mashqlarda mustahkamlash muhim.</li><li><strong>User Story xatosi:</strong> &quot;So that...&quot; qismini yozmasdan shunchaki texnik funksiyani ko&#39;rsatish keng uchraydi. Har bir amal orqasida insoniy qiymat yotishi shartligini tushuntiring.</li></ul>',11))])])}const z=n(h,[["render",q]]);export{x as __pageData,z as default};
